describe('Duplicate Record Feature', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.login('testuser@example.com', 'password123');
    cy.wait(1000);
  });

  it('should duplicate an existing record with one click', () => {
    cy.get('[data-testid="records-table"]').should('be.visible');
    cy.get('[data-testid="record-row"]').first().as('firstRecord');

    cy.get('@firstRecord').within(() => {
      cy.get('[data-testid="record-name"]').invoke('text').as('originalName');
      cy.get('[data-testid="duplicate-btn"]').click();
    });

    cy.get('[data-testid="duplicate-modal"]').should('be.visible');
    cy.get('[data-testid="confirm-duplicate-btn"]').click();

    cy.get('[data-testid="success-toast"]').should('contain', 'Record duplicated successfully');

    cy.get('[data-testid="records-table"]').within(() => {
      cy.get('[data-testid="record-row"]').should('have.length.greaterThan', 1);
    });

    cy.get('@originalName').then((originalName) => {
      cy.get('[data-testid="record-name"]').first().should('contain', originalName);
    });
  });

  it('should handle duplicate action for record with special characters and complex data', () => {
    cy.get('[data-testid="records-table"]').should('be.visible');

    cy.get('[data-testid="record-row"]').contains('Special & Record #123').as('specialRecord');

    cy.get('@specialRecord').within(() => {
      cy.get('[data-testid="duplicate-btn"]').click();
    });

    cy.get('[data-testid="duplicate-modal"]').should('be.visible');
    cy.get('[data-testid="duplicate-modal"]').within(() => {
      cy.get('[data-testid="modal-title"]').should('contain', 'Duplicate Record');
      cy.get('[data-testid="confirm-duplicate-btn"]').should('be.enabled');
    });

    cy.get('[data-testid="confirm-duplicate-btn"]').click();

    cy.get('[data-testid="success-toast"]').should('be.visible');
    cy.get('[data-testid="success-toast"]').should('contain', 'Record duplicated successfully');

    cy.get('[data-testid="records-table"]').within(() => {
      cy.get('[data-testid="record-name"]').filter(':contains("Special & Record #123")').should('have.length', 2);
    });
  });

  it('should cancel duplicate action without creating a new record', () => {
    cy.get('[data-testid="records-table"]').should('be.visible');
    cy.get('[data-testid="record-row"]').first().within(() => {
      cy.get('[data-testid="duplicate-btn"]').click();
    });

    cy.get('[data-testid="duplicate-modal"]').should('be.visible');
    cy.get('[data-testid="cancel-duplicate-btn"]').click();

    cy.get('[data-testid="duplicate-modal"]').should('not.exist');
    cy.get('[data-testid="success-toast"]').should('not.exist');

    cy.get('[data-testid="records-table"]').within(() => {
      cy.get('[data-testid="record-row"]').then(($rows) => {
        const initialCount = $rows.length;
        cy.get('[data-testid="record-row"]').should('have.length', initialCount);
      });
    });
  });

  it('should display error message when duplicate action fails', () => {
    cy.intercept('POST', '/api/records/*/duplicate', {
      statusCode: 500,
      body: { error: 'Server error occurred' }
    }).as('duplicateError');

    cy.get('[data-testid="records-table"]').should('be.visible');
    cy.get('[data-testid="record-row"]').first().within(() => {
      cy.get('[data-testid="duplicate-btn"]').click();
    });

    cy.get('[data-testid="duplicate-modal"]').should('be.visible');
    cy.get('[data-testid="confirm-duplicate-btn"]').click();

    cy.wait('@duplicateError');
    cy.get('[data-testid="error-toast"]').should('be.visible');
    cy.get('[data-testid="error-toast"]').should('contain', 'Failed to duplicate record');
  });

  it('should disable duplicate button for read-only records', () => {
    cy.get('[data-testid="records-table"]').should('be.visible');
    cy.get('[data-testid="record-row"]').filter('[data-readonly="true"]').first().within(() => {
      cy.get('[data-testid="duplicate-btn"]').should('be.disabled');
    });
  });
});
